DO $$ BEGIN IF current_database()<>'chat_sales_lab' THEN RAISE EXCEPTION 'Lab only'; END IF; END $$;
UPDATE outbound_commands oc SET status='dead_letter' FROM broadcast_message_tests t WHERE oc.id=t.outbound_command_id AND oc.workspace_id=t.workspace_id AND oc.workspace_id='b1111111-1111-4111-8111-111111111111' AND oc.channel_instance_id='d2222222-2222-4222-8222-222222222222' AND oc.idempotency_key LIKE 'btest_%' AND oc.status='pending';
UPDATE messages m SET delivery_status='failed',status_rank=-1 FROM outbound_commands oc JOIN broadcast_message_tests t ON t.outbound_command_id=oc.id AND t.workspace_id=oc.workspace_id WHERE m.id=oc.message_id AND m.workspace_id=oc.workspace_id AND oc.workspace_id='b1111111-1111-4111-8111-111111111111' AND oc.channel_instance_id='d2222222-2222-4222-8222-222222222222' AND oc.status='dead_letter';
